package org.eternalself.umbrielremote;
import static org.junit.Assert.*;
import android.app.*;import android.graphics.Color;import android.view.*;import android.widget.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class)
@Config(application=UiTestApplication.class,sdk=36,qualifiers="w412dp-h892dp-port-night-mdpi")
public class LanguagePaletteTest {
 @Before public void setup(){RemoteService.instance=null;MainActivity.current.clear();RuntimeEnvironment.getApplication().getSharedPreferences("connection",0).edit().clear().commit();}
 @After public void clear(){RemoteService.instance=null;MainActivity.current.clear();}
 @Test public void englishHomeAndExactMessagesLeaveUserContentUnchanged(){Application app=RuntimeEnvironment.getApplication();app.getSharedPreferences("appearance",0).edit().putString("language","en").commit();Messages.init(app);assertEquals("Text and keyboard",Messages.t("Texto y teclado"));assertEquals("clipboard-get",Messages.t("clipboard-get"));assertEquals("Mi canción personal",Messages.t("Mi canción personal"));ActivityController<MainActivity> screen=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity a=screen.get();assertEquals("Home",((Button)a.findViewById(android.R.id.content).findViewWithTag("nav-0")).getText().toString());a.navigate(3);assertEquals("Settings",((Button)a.findViewById(android.R.id.content).findViewWithTag("nav-3")).getText().toString());}finally{screen.pause().stop().destroy();}}
 private double luminance(int color){double[] c={Color.red(color)/255.0,Color.green(color)/255.0,Color.blue(color)/255.0};for(int i=0;i<3;i++)c[i]=c[i]<=.04045?c[i]/12.92:Math.pow((c[i]+.055)/1.055,2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2];}
 private double contrast(int a,int b){double x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 @Test public void palettesPreserveReadableTextInBothThemes(){for(String id:AppearanceSettings.IDS)for(boolean dark:new boolean[]{false,true}){int[] c=AppearanceSettings.colors(id,dark);for(int bg=0;bg<3;bg++){assertTrue(id+" body contrast",contrast(c[3],c[bg])>=4.5);assertTrue(id+" supporting contrast",contrast(c[4],c[bg])>=4.5);}int accent=AppearanceSettings.accent(id,dark,dark?0xffc8bfff:0xff6350a4);int foreground=luminance(accent)>.179?Color.BLACK:Color.WHITE;assertTrue(contrast(accent,foreground)>=4.5);}}
 @Test public void appearanceRecreationPreservesSelectionAndConnection(){HomeNavigationTest.Computer computer=new HomeNavigationTest.Computer();RemoteService.instance=computer;ActivityController<MainActivity> screen=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity a=screen.get();a.pendingFiles.add(android.net.Uri.parse("content://fixture/file"));a.getSharedPreferences("appearance",0).edit().putString("palette","rose").putString("theme","dark").commit();screen.recreate();MainActivity recreated=screen.get();assertEquals(1,recreated.pendingFiles.size());assertEquals("content://fixture/file",recreated.pendingFiles.get(0).toString());UiDesign ui=new UiDesign(recreated);assertEquals(Color.parseColor("#1d1519"),ui.background);assertSame(computer,RemoteService.instance);assertTrue(computer.isAuthorized());}finally{screen.pause().stop().destroy();}}
}
